$translations['Registration of your EPESI installation with %s will allow you to browse and make purchases in %sEPESI Store%s and receive notifications via e-mail about important updates.']='Epesi Kaydınızı yaparak Epesi yüklemeleri ile %s Epesi\'nin %EPESI Store%s mağazasından bildirimleri ve önemli güncellemeleri alabileceksiniz.';
$translations['Once the registration is complete you will receive a %sLicense Key%s.']='Kaydınız başarı ile laındı yakında bir Lisans anahtarı alacaksınız %License Key&s.';
$translations['This unique License Key will be used to identify your installation and allow you to download and use modules you purchase. Please note that %sEPESI License Key%s can not be copied to any other EPESI installation.']='Bu Lisans anahtarı ile yüklemeleri alabilir ve modülleri satın alabilirsiniz lütfen not edin %sEPESI License Key%s benzersizdir başka EPESI yüklemelerine kopyalanamaz.';
$translations['If necessary, you can move your installation to another server and keep your EPESI License Key, but at any given time no two installations can use the same EPESI License Key.']='Gerektiğinde EPESI yazılmını başka sunucuya taşıyabilirsiniz Lisans anahtarınızla. Ancak aynı EPESI Lisans Anahtarını birden fazla yüklemede kullanamazsınız';
$translations['Allowing unsecure connection will cause all the data to be transferred without encryption. This creates opportunity for third parties to capture the data being transmitted, including your License Key. Please note that License Key should be kept confidential and that using the same License Key on several EPESI installations is a direct violation of Terms of Service and will result in termination of the License Key.']='Kabul edilen güvenilir olmayan bağlantılarda veriler herhangi bir şifreleme türü olmadan transfer edilir, bu durumda üçüncü parti yazılımlar ile Lisans anahtarınız alınabilir. Tavsiyemiz Lisans anahtarınızı bir yere not almanız ve lisans anahtarınızı yüklemede kullanamadığınızda bizlere bildirmeniz.';
$translations['The only data being sent is the values of the fields presented below and the translated strings, we do not receive any other information contained in EPESI.']='Sadece Dil Çevirme Bölümündeki Çevrilen veri değerleri alınır. Herhangi bir EPESI içeriğiniz kesinlikle alınmaz.';
$translations['You can also change your Translations Contribution settings at later time.']='Dilediğiniz zaman (Translations Contribution) Çevirme Paylaşımı ayarlarından bunu kapatabilirsiniz.';
